/*
 Problem: 2267.  Check if There Is a Valid Parentheses String Path
 Language: cpp
 Runtime: 70 ms (56.39%)
 Memory: 136 MB (29.01%)
 Tags: Array, Dynamic Programming, Matrix, Bracket Sequences
*/
class Solution {
public:
    bool hasValidPath(vector<vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int pathLength = m + n - 1;

        if (pathLength % 2 != 0 ||
            grid[0][0] != '(' ||
            grid[m - 1][n - 1] != ')') {
            return false;
        }

        vector<vector<vector<int>>> memo(
            m, vector<vector<int>>(n, vector<int>(pathLength + 1, -1))
        );

        auto dfs = [&](auto&& self, int row, int col, int balance) -> bool {
            balance += grid[row][col] == '(' ? 1 : -1;

            int remaining = (m - 1 - row) + (n - 1 - col);
            if (balance < 0 || balance > remaining) {
                return false;
            }

            if (row == m - 1 && col == n - 1) {
                return balance == 0;
            }

            int& result = memo[row][col][balance];
            if (result != -1) {
                return result;
            }

            bool valid =
                (row + 1 < m && self(self, row + 1, col, balance)) ||
                (col + 1 < n && self(self, row, col + 1, balance));

            result = valid;
            return valid;
        };

        return dfs(dfs, 0, 0, 0);
    }
};
